script.setup:
// 3,500 boids; every frame Flatbush indexes their positions and each boid asks it for the
// flockmates within its view box, so the flocking rules never compare every pair.
const mod = await ctx.utils.import("https://esm.sh/flatbush@4.6.2");
const Flatbush = mod.default ?? mod;
const N = 3500;
const [w0, h0] = ctx.resolution;
const H = 1000, W = H * w0 / h0;
const px = new Float32Array(N), py = new Float32Array(N), vx = new Float32Array(N), vy = new Float32Array(N);
for (let i = 0; i < N; i++) {
  px[i] = Math.random() * W; py[i] = Math.random() * H;
  const a = Math.random() * Math.PI * 2; vx[i] = Math.cos(a) * 80; vy[i] = Math.sin(a) * 80;
}
const gl = ctx.gl;
const vao = gl.createVertexArray(), buffer = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 16, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 2, gl.FLOAT, false, 16, 8);
gl.bindVertexArray(null);
const lineVao = gl.createVertexArray(), lineBuffer = gl.createBuffer();
gl.bindVertexArray(lineVao); gl.bindBuffer(gl.ARRAY_BUFFER, lineBuffer);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 16, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 2, gl.FLOAT, false, 16, 8);
gl.bindVertexArray(null);
const program = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position; layout(location=1) in vec2 a_info;
uniform vec2 u_view; uniform vec2 u_offset; out vec2 v_info;
void main(){ v_info = a_info; gl_Position = vec4(a_position / u_view * 2.0 - 1.0 + u_offset, 0.0, 1.0); }`, `#version 300 es
precision highp float; in vec2 v_info; out vec4 outColor; uniform vec3 u_colorA; uniform vec3 u_colorB;
void main(){
  // x: heading (0..1 around the circle), y: brightness (lines use y > 1 for white).
  if (v_info.y > 1.5) { outColor = vec4(vec3(1.0, 0.95, 0.8) * (v_info.y - 1.5), 1.0); return; }
  float t = 0.5 + 0.5 * cos(v_info.x * 6.2831853);
  outColor = vec4(mix(u_colorA, u_colorB, t) * v_info.y, 1.0);
}`);
Object.assign(ctx.state, { Flatbush, N, W, H, px, py, vx, vy, vao, buffer, lineVao, lineBuffer, program, tris: new Float32Array(N * 12), moved: false, watched: 0 });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const { N, W, H, px, py, vx, vy } = s;
const dt = Math.min(ctx.dt, 1 / 30);
// Index this frame's positions.
const index = new s.Flatbush(N);
for (let i = 0; i < N; i++) index.add(px[i], py[i]);
index.finish();
s.moved ||= ctx.mouse[0] !== 0.5 || ctx.mouse[1] !== 0.5;
const mx = ctx.mouse[0] * W, my = (1 - ctx.mouse[1]) * H;
// Hover picks the boid to inspect (Flatbush's nearest-neighbor query); the button scares the flock.
if (s.moved) s.watched = index.neighbors(mx, my, 1)[0] ?? s.watched;
const R = u.u_radius, sep = R * 0.4, speed = 90 * u.u_speed;
let watchedMates = [];
for (let i = 0; i < N; i++) {
  const mates = index.search(px[i] - R, py[i] - R, px[i] + R, py[i] + R);
  let ax = 0, ay = 0, cx = 0, cy = 0, sxp = 0, syp = 0, n = 0;
  for (const j of mates) {
    if (j === i) continue;
    const dx = px[j] - px[i], dy = py[j] - py[i], d2 = dx * dx + dy * dy;
    if (d2 > R * R) continue;
    n++; ax += vx[j]; ay += vy[j]; cx += dx; cy += dy;
    if (d2 < sep * sep) { const k = 1 / Math.max(d2, 1); sxp -= dx * k; syp -= dy * k; }
    if (i === s.watched) watchedMates.push(j);
  }
  let fx = 0, fy = 0;
  if (n) {
    fx += (ax / n - vx[i]) * u.u_align + cx / n * u.u_cohesion + sxp * sep * 60 * u.u_separation;
    fy += (ay / n - vy[i]) * u.u_align + cy / n * u.u_cohesion + syp * sep * 60 * u.u_separation;
  }
  if (s.moved && ctx.mouseDown) {
    const dx = px[i] - mx, dy = py[i] - my, d2 = dx * dx + dy * dy;
    if (d2 < 160 * 160) { const k = 9000 / Math.max(d2, 100); fx += dx * k * 0.1; fy += dy * k * 0.1; }
  }
  vx[i] += fx * dt; vy[i] += fy * dt;
  const v = Math.hypot(vx[i], vy[i]) || 1, target = Math.min(Math.max(v, speed * 0.6), speed * 1.6);
  vx[i] *= target / v; vy[i] *= target / v;
}
// Move and wrap around; then a small triangle per boid, pointing along its velocity.
const boid = 6 * u.u_size;
for (let i = 0; i < N; i++) {
  px[i] = (px[i] + vx[i] * dt + W) % W; py[i] = (py[i] + vy[i] * dt + H) % H;
  const v = Math.hypot(vx[i], vy[i]) || 1, dx = vx[i] / v, dy = vy[i] / v;
  const heading = Math.atan2(dy, dx) / (Math.PI * 2) + 0.5;
  const lit = i === s.watched ? 1.4 : 0.95, size = i === s.watched ? boid * 2.2 : boid;
  s.tris.set([px[i] + dx * size * 1.6, py[i] + dy * size * 1.6, heading, lit,
    px[i] - dx * size - dy * size * 0.7, py[i] - dy * size + dx * size * 0.7, heading, lit * 0.5,
    px[i] - dx * size + dy * size * 0.7, py[i] - dy * size - dx * size * 0.7, heading, lit * 0.5], i * 12);
}
// The inspected boid: its query box and lines to the flockmates the index returned.
const q = s.watched, lines = [];
const L = (x0, y0, x1, y1, b) => lines.push(x0, y0, 0, b, x1, y1, 0, b);
L(px[q] - R, py[q] - R, px[q] + R, py[q] - R, 2.6); L(px[q] + R, py[q] - R, px[q] + R, py[q] + R, 2.6);
L(px[q] + R, py[q] + R, px[q] - R, py[q] + R, 2.6); L(px[q] - R, py[q] + R, px[q] - R, py[q] - R, 2.6);
for (const j of watchedMates) L(px[q], py[q], px[j], py[j], 2.4);
gl.clearColor(0.025, 0.028, 0.04, 1); gl.clear(gl.COLOR_BUFFER_BIT);
gl.useProgram(s.program);
ctx.utils.setUniforms(s.program, { u_view: [W, H], u_offset: [0, 0], u_colorA: u.u_colorA, u_colorB: u.u_colorB });
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
gl.bindVertexArray(s.vao); gl.bindBuffer(gl.ARRAY_BUFFER, s.buffer);
gl.bufferData(gl.ARRAY_BUFFER, s.tris, gl.DYNAMIC_DRAW);
gl.drawArrays(gl.TRIANGLES, 0, N * 3);
gl.bindVertexArray(s.lineVao); gl.bindBuffer(gl.ARRAY_BUFFER, s.lineBuffer);
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(lines), gl.DYNAMIC_DRAW);
// WebGL lines are 1 px; two shifted passes make them read at any size.
for (const o of [[0, 0], [1.5 / w, 1.5 / h]]) { ctx.utils.setUniforms(s.program, { u_offset: o }); gl.drawArrays(gl.LINES, 0, lines.length / 4); }
gl.disable(gl.BLEND);
gl.bindVertexArray(null);
ctx.publish("flockmates", watchedMates.length);
